INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(801, 'Genesis 29:19', 'Genesis', 29, 19, '&nbsp;لابن جواب ورکړو، ”هغه چې بل چا له ورکوم د هغې نه دا ښۀ ده چې تا له يې درکړم، دلته زما سره اوسېږه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(802, 'Genesis 29:20', 'Genesis', 29, 20, '&nbsp;نو يعقوب د راحيل دپاره اووۀ کاله خِدمت وکړو او هغه وخت په هغۀ باندې صِرف د يو څو ورځو په شان تېر شو، ځکه چې هغۀ د راحيل سره مينه کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(803, 'Genesis 29:21', 'Genesis', 29, 21, '&nbsp;بيا يعقوب لابن ته وفرمائيل، ”هغه وخت پوره شوے دے، ستا لور راکړه چې وادۀ يې کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(804, 'Genesis 29:22', 'Genesis', 29, 22, '&nbsp;نو لابن د وادۀ روټۍ وکړه او ټول خلق يې راوغوښتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(805, 'Genesis 29:23', 'Genesis', 29, 23, '&nbsp;خو په هغه شپه، د راحيل په ځائ هغۀ لِياه يعقوب له بوتله او يعقوب د هغې سره څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(806, 'Genesis 29:24', 'Genesis', 29, 24, '&nbsp;لابن خپله وينځه زِلفه خپلې لور لِياه له د خِدمتګارې په توګه ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(807, 'Genesis 29:25', 'Genesis', 29, 25, '&nbsp;چې کله سحر شو، يعقوب ته پته ولګېده چې دا خو لِياه ده. هغه لابن له ورَغلو او ورته يې وفرمائيل، ”دا تا زما سره څۀ کړى دى؟ ما خو د راحيل دپاره خِدمت کړے دے. تا زۀ ولې دوکه کړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(808, 'Genesis 29:26', 'Genesis', 29, 26, '&nbsp;لابن جواب ورکړو، ”دلته دا رِواج نۀ دے چې کشره لور دې د مشرې نه مخکښې وادۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(809, 'Genesis 29:27', 'Genesis', 29, 27, '&nbsp;صبر وکړه چې د وادۀ اوومه تېره شى، نو زۀ به راحيل هم تا له درکړم، خو کۀ تۀ زما نور اووۀ کاله خِدمت وکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(810, 'Genesis 29:28', 'Genesis', 29, 28, '&nbsp;يعقوب راضى شو او چې کله د وادۀ اووۀ ورځې پوره شوې، لابن هغۀ له خپله لور راحيل هم ورکړه چې ښځه يې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(811, 'Genesis 29:29', 'Genesis', 29, 29, '&nbsp;لابن خپله وينځه بِلهاه خپلې لور راحيل له ورکړه چې خِدمتګاره يې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(812, 'Genesis 29:30', 'Genesis', 29, 30, '&nbsp;يعقوب د راحيل سره هم څملاستو او هغۀ د هغې سره د لِياه نه زياته مينه کوله. بيا هغۀ د لابن نور اووۀ کاله خِدمت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(813, 'Genesis 29:31', 'Genesis', 29, 31, '&nbsp;چې کله مالِک خُدائ دا وليدل چې د لِياه سره مينه نۀ کېدله، نو مالِک خُدائ هغې له اولاد ورکړو، خو راحيل شنډه پاتې شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(814, 'Genesis 29:32', 'Genesis', 29, 32, '&nbsp;لِياه اُميدواره شوه او يو زوئ يې پېدا شو. هغې وفرمائيل، ”مالِک خُدائ زۀ په تکليف کښې ليدلې يم او اوس به زما خاوند زما سره مينه کوى.“ نو د هغۀ نوم يې روبين کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(815, 'Genesis 29:33', 'Genesis', 29, 33, '&nbsp;هغه بيا اُميدواره شوه او يو بل زوئ يې پېدا شو. نو هغې وفرمائيل، ”مالِک خُدائ ما له دا زوئ هم راکړے دے، ځکه چې هغۀ ته پته وه چې زما نه کرکه کيږى.“ نو د هغۀ نوم يې شمعون کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(816, 'Genesis 29:34', 'Genesis', 29, 34, '&nbsp;هغه يو ځل بيا اُميدواره شوه او د هغې يو بل زوئ وشو. هغې وفرمائيل، ”زما د خاوند زړۀ به اوس په ما پورې نور هم تړلے وى، ځکه چې زما نه د هغۀ درې زامن پېدا شول.“ نو د هغۀ نوم يې ليوى کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(817, 'Genesis 29:35', 'Genesis', 29, 35, '&nbsp;بيا هغه يو ځل بيا اُميدواره شوه او يو بل زوئ يې پېدا شو. هغې وفرمائيل، ”دا ځل به زۀ د مالِک خُدائ ثناء ووايم.“ نو هغې د هغۀ نوم يهوداه کېښودو. بيا د هغې نور بچى پېدا نۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(818, 'Genesis 30:1', 'Genesis', 30, 1, '&nbsp;خو د راحيل نه د يعقوب هيڅ بچى پېدا شوى نۀ وُو. نو په راحيل خپله خور بده لګېده او يعقوب ته يې ووئيل، ”زۀ غواړم چې زما نه دې هم بچى وى ګنې زۀ به مړه شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(819, 'Genesis 30:2', 'Genesis', 30, 2, '&nbsp;يعقوب راحيل ته غصه شو او وې فرمائيل، ”زۀ خو څۀ خُدائ پاک نۀ يم چې تۀ مې د بچو نه محرومه کړې يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(820, 'Genesis 30:3', 'Genesis', 30, 3, '&nbsp;هغې ووئيل، ”زما وينځه بِلهاه بوځه، د هغې سره څمله، نو د هغې نه به زما دپاره بچى پېدا شى. او د هغې په وجه به زما کور آباد شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(821, 'Genesis 30:4', 'Genesis', 30, 4, '&nbsp;نو هغې بِلهاه خپل خاوند له ورکړه او هغه د هغې سره څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(822, 'Genesis 30:5', 'Genesis', 30, 5, '&nbsp;بِلهاه اُميدواره شوه او د يعقوب يو زوئ ترې پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(823, 'Genesis 30:6', 'Genesis', 30, 6, '&nbsp;راحيل ووئيل، ”خُدائ پاک زما په حق کښې فېصله کړې ده. هغۀ زما سوال اورېدلے دے او ما له يې يو زوئ راکړے دے.“ نو د هغۀ نوم يې دان کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(824, 'Genesis 30:7', 'Genesis', 30, 7, '&nbsp;بِلهاه يو ځل بيا اُميدواره شوه او د يعقوب ترې دوېم زوئ وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(825, 'Genesis 30:8', 'Genesis', 30, 8, '&nbsp;راحيل ووئيل، ”ما د خپلې خور سره لويه مقابله کړې ده. خو ما ګټلې ده.“ نو د هغۀ نوم يې نفتالى کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(826, 'Genesis 30:9', 'Genesis', 30, 9, '&nbsp;چې کله لِياه ته دا پته ولګېده چې د هغې به نور بچى نۀ کيږى، نو هغې خپله وينځه زِلفه يعقوب له ورکړه چې ښځه يې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(827, 'Genesis 30:10', 'Genesis', 30, 10, '&nbsp;بيا د زِلفه نه د يعقوب يو زوئ وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(828, 'Genesis 30:11', 'Genesis', 30, 11, '&nbsp;لِياه ووئيل، ”زۀ بختوره يم.“ نو د هغۀ نوم يې جاد کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(829, 'Genesis 30:12', 'Genesis', 30, 12, '&nbsp;د زِلفه نه د يعقوب يو بل زوئ وشو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(830, 'Genesis 30:13', 'Genesis', 30, 13, '&nbsp;او لِياه ووئيل، ”زۀ څومره خوشحاله يم. اوس به ښځې ما ته خوشحاله وائى.“ نو هغې د هغۀ نوم آشر کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(831, 'Genesis 30:14', 'Genesis', 30, 14, '&nbsp;د غنمو د لَو په وخت روبين پټو ته لاړو او هلته يې هغه بوټى وموندل د کومو په ذريعه چې د زنانه حمل لګېدلو او هغه يې خپلې مور لِياه له راوړل. راحيل لِياه ته ووئيل، ”ما له خو د هغه بوټو نه لږ راکړه کوم چې ستا زوئ راوړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(832, 'Genesis 30:15', 'Genesis', 30, 15, '&nbsp;لِياه جواب ورکړو، ”دا څۀ وړه خبره ده چې زما خاوند دې رانه قبضه کړے دے؟ او اوس تۀ وائې چې ما له هغه د حمل بوټى راکړه کوم چې ستا زوئ راوړى دى.“ راحيل ووئيل، ”کۀ تۀ ما له ستا د زوئ هغه بوټى راکړې، نو تۀ نن شپه د يعقوب سره څملاستے شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(833, 'Genesis 30:16', 'Genesis', 30, 16, '&nbsp;چې کله يعقوب ماښام د پټو نه راغلو، لِياه بهر مِلاوېدو له هغۀ له ورغله او وې وئيل، ”تۀ به خامخا نن زما سره څملې، ځکه چې ما د خپل زوئ د حمل بوټى ستا په سر ورکړى دى.“ نو په هغه شپه د هغې سره څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(834, 'Genesis 30:17', 'Genesis', 30, 17, '&nbsp;خُدائ پاک د لِياه سوال واورېدو او هغه اُميدواره شوه او د يعقوب ترې پينځم زوئ وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(835, 'Genesis 30:18', 'Genesis', 30, 18, '&nbsp;لِياه ووئيل، ”خُدائ پاک ما له خپل اجر راکړے دے، ځکه چې ما خپله وينځه خپل خاوند له ورکړه.“ نو هغې په خپل زوئ يساکار نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(836, 'Genesis 30:19', 'Genesis', 30, 19, '&nbsp;لِياه بيا اُميدواره شوه او د يعقوب ترې شپږم زوئ وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(837, 'Genesis 30:20', 'Genesis', 30, 20, '&nbsp;هغې ووئيل، ”خُدائ پاک ما له يوه ښُکلې تُحفه راکړې ده. اوس به زما خاوند زما قدر کوى، ځکه چې زما نه د هغۀ شپږ زامن پېدا شوى دى.“ نو هغې د هغۀ نوم زبولون کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(838, 'Genesis 30:21', 'Genesis', 30, 21, '&nbsp;وروستو د هغې يوه لور پېدا شوه، چې د هغې نوم يې دينه کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(839, 'Genesis 30:22', 'Genesis', 30, 22, '&nbsp;بيا خُدائ پاک راحيل راياده کړه، هغۀ د هغې سوال قبول کړو او هغې له يې هم بچى ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(840, 'Genesis 30:23', 'Genesis', 30, 23, '&nbsp;هغه اُميدواره شوه او يو زوئ يې پېدا شو. هغې ووئيل، ”خُدائ پاک ما له يو زوئ راکړو نو زۀ يې د پېغور نه خلاصه کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(841, 'Genesis 30:24', 'Genesis', 30, 24, '&nbsp;نو هغې د هغۀ نوم يوسف کېښودو او ووئيل، ”مالِک خُدائ دې ما له يو بل زوئ هم راکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(842, 'Genesis 30:25', 'Genesis', 30, 25, '&nbsp;د يوسف د پېدا کېدو نه پس، يعقوب لابن ته وفرمائيل، ”ما له اجازت راکړه، چې زۀ خپل کور او خپل مُلک ته واپس لاړ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(843, 'Genesis 30:26', 'Genesis', 30, 26, '&nbsp;ما له زما ښځې او زامن راکړه چې ما ستا خِدمت کولو کښې ګټلى دى او زۀ به لاړ شم. ځکه چې تا ته پته ده چې ما ستا څومره ښۀ خِدمت کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(844, 'Genesis 30:27', 'Genesis', 30, 27, '&nbsp;لابن هغۀ ته ووئيل، ”کۀ زۀ ستا په نظر کښې ښۀ يم نو يوه خبره به وکړم، ما ته غېبانه پته لګېدلې ده چې هم ستا په وجه مالِک خُدائ ما له برکت راکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(845, 'Genesis 30:28', 'Genesis', 30, 28, '&nbsp;چې تۀ څومره مزدورى غواړې نو ووايه او زۀ به يې درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(846, 'Genesis 30:29', 'Genesis', 30, 29, '&nbsp;يعقوب جواب ورکړو، ”تا ته په خپله پته ده چې ما ستا څومره خِدمت کړے دے او ستا رَمې زما سره څومره زياتې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(847, 'Genesis 30:30', 'Genesis', 30, 30, '&nbsp;ځکه چې تا زما د راتلو نه مخکښې لږ څۀ لرل او اوس ډېر زيات شول او چې ما چرته هم ستا رَمې بوتلى دى مالِک خُدائ تا له برکت درکړے دے. اوس هغه وخت راغلے دے چې زۀ د خپل خاندان خيال وساتم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(848, 'Genesis 30:31', 'Genesis', 30, 31, '&nbsp;لابن ترې تپوس وکړو، ”زۀ تا له څۀ درکړم؟“ يعقوب جواب ورکړو، ”زۀ درنه هيڅ مزدورى نۀ غواړم. زۀ به بيا ستا رَمې څروم او ساتم کۀ تۀ زما دپاره يو کار وکړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(849, 'Genesis 30:32', 'Genesis', 30, 32, '&nbsp;نن به زۀ ستا په ټولو رَمو کښې وګرځم او هر تور ګډُورے او ټولې ټکى ټکى او برَګې چېلۍ به راوباسم. بس دا ټوله مزدورى ده چې زۀ يې غواړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(850, 'Genesis 30:33', 'Genesis', 30, 33, '&nbsp;په راتلونکى وخت کښې به تا ته په آسانۍ سره پته ولګى کۀ زۀ رښتونے سړے يم. چې کله تۀ بيا د دې کتلو له راشې، کۀ زما سره توره ګډه، ټکى ټکى يا برَګې چېلۍ نۀ وى، نو تۀ به پوهه شې چې پټې کړے شوې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(851, 'Genesis 30:34', 'Genesis', 30, 34, '&nbsp;لابن جواب ورکړو، ”ټيک ده. مونږ به هم ستا په خبره کار کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(852, 'Genesis 30:35', 'Genesis', 30, 35, '&nbsp;خو په هغه ورځ لابن هغه چېلى چې کرښې پرې وې يا برَګ وُو هغه يې بېل کړل او هغه ټولې چېلۍ چې ټکى ټکى او برَګې وې او تورې ګډې يې هم ترې لرې کړې. او هغۀ دا د خپلو زامنو په حواله کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(853, 'Genesis 30:36', 'Genesis', 30, 36, '&nbsp;او بيا د دې رَمې سره د يعقوب نه د درېو ورځو د مزل برابر لرې لاړو. يعقوب د لابن پاتې رَمې ساتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(854, 'Genesis 30:37', 'Genesis', 30, 37, '&nbsp;يعقوب د سپېدار، بادام او چِنار د ونو شنې څانګې راماتې کړې او پوستکى يې ترې لرې کړل نو په دې څانګو باندې سپينې کرښې راووتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(855, 'Genesis 30:38', 'Genesis', 30, 38, '&nbsp;هغۀ دا څانګې د رَمو په مخکښې د اوبو په ډيګو کښې کېښودې. هغۀ دا هلته پرېښودې، ځکه چې کله به څاروى اوبو څښلو له راتلل نو هلته به مال کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(856, 'Genesis 30:39', 'Genesis', 30, 39, '&nbsp;نو چې دا د څانګو په مخکښې مال شوې نو هغوئ د کرښو والا، ټکى ټکى او برَګ بچى راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(857, 'Genesis 30:40', 'Genesis', 30, 40, '&nbsp;يعقوب ګډې د چېلو نه بېلې ساتلې او هغۀ د هغوئ مخونه د لابن د کرښو والا او تورو څاروو ته کړل. نو هغۀ خپله رمه جوړه کړه او دا يې د لابن د رَمې نه جدا کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(858, 'Genesis 30:41', 'Genesis', 30, 41, '&nbsp;چې کله تکړه څاروى مال کېدل، يعقوب د هغوئ په مخکښې د اوبو په هغه ډيګو کښې څانګې کېښودې، نو د هغه څانګو په خوا کښې به څاروى مال کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(859, 'Genesis 30:42', 'Genesis', 30, 42, '&nbsp;خو هغۀ د کمزورو څاروو په مخکښې هغه څانګې کېنۀ ښودلې. نو هغه ټول کمزورى څاروى د لابن شول او تکړه ټول د يعقوب شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(860, 'Genesis 30:43', 'Genesis', 30, 43, '&nbsp;نو يعقوب ډېر مالدار شولو. د هغۀ ډېرې رَمې نوکران، اوښان او خرۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(861, 'Genesis 31:1', 'Genesis', 31, 1, '&nbsp;نو يعقوب واورېدل چې د لابن زامن وائى، ”زمونږ د پلار سره چې څۀ هم وُو نو هغه يعقوب د خپل ځان سره وړى دى. د هغۀ سره چې څومره دولت دے هغه ټول زمونږ د پلار وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(862, 'Genesis 31:2', 'Genesis', 31, 2, '&nbsp;هغۀ ته دا پته هم ولګېده چې لابن ورسره اوس دومره ښۀ نۀ دے لکه څومره چې ورسره مخکښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(863, 'Genesis 31:3', 'Genesis', 31, 3, '&nbsp;بيا مالِک خُدائ هغۀ ته وفرمائيل، ”واپس د خپل پلار نيکۀ مُلک ته او خپلو خپلوانو له لاړ شه. زۀ به ستا مل يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(864, 'Genesis 31:4', 'Genesis', 31, 4, '&nbsp;نو يعقوب راحيل او لِياه راوغوښتلې چې د هغۀ سره په پټى کښې مِلاو شى چرته چې د هغۀ رَمې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(865, 'Genesis 31:5', 'Genesis', 31, 5, '&nbsp;هغۀ هغوئ ته وفرمائيل، ”ما ته پته لګېدلې ده چې ستاسو پلار زما سره دومره ښۀ نۀ دے لکه چې څومره مخکښې وو، خو زما د پلار خُدائ پاک زما مل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(866, 'Genesis 31:6', 'Genesis', 31, 6, '&nbsp;تاسو دواړو ته پته ده چې ما د خپل ټول طاقت سره ستاسو د پلار خِدمت وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(867, 'Genesis 31:7', 'Genesis', 31, 7, '&nbsp;خو بيا هم هغۀ زۀ دوکه کړم او لس ځل يې زما مزدورى بدله کړې ده. خو خُدائ پاک هغه ما ته څۀ نقصان رسولو ته پرې نۀ ښودلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(868, 'Genesis 31:8', 'Genesis', 31, 8, '&nbsp;چې کله نه هم لابن دا وئيلى دى چې برَګې چېلۍ به ستا مزدورى وى، نو ټولو رَمو برَګ بچى راوړل. چې کله هغۀ ووئيل، د کرښو والا چېلۍ به ستا مزدورى وى، نو ټولو رَمو د کرښو والا بچى راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(869, 'Genesis 31:9', 'Genesis', 31, 9, '&nbsp;خُدائ پاک ستاسو د پلار نه رَمې اخستې دى او هغه يې ما له راکړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(870, 'Genesis 31:10', 'Genesis', 31, 10, '&nbsp;د څاروو د وار راوړو په وخت کښې ما يو خوب وليدو او ما وکتل چې کوم چېلى چې چېلۍ مال کوى هغه د کرښو والا، ټکى ټکى او برَګ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(871, 'Genesis 31:11', 'Genesis', 31, 11, '&nbsp;د خُدائ پاک فرښتې ما ته په خوب کښې ووئيل، يعقوبه، ما جواب ورکړو، زۀ حاضر يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(872, 'Genesis 31:12', 'Genesis', 31, 12, '&nbsp;هغې ووئيل، وګوره، هغه ټول چېلى کوم چې چېلۍ مال کوى هغه د کرښو والا ټکى ټکى او برَګ دى. زۀ داسې ځکه کوم چې لابن تا سره څۀ کوى نو ما ته د هغه هر څۀ پته ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(873, 'Genesis 31:13', 'Genesis', 31, 13, '&nbsp;زۀ خُدائ پاک يم چې په بيت‌ايل کښې تا ته راڅرګند شوے وم، چې هلته تا يو کاڼے د يادګار په توګه وقف کړو او په هغې دې تېل واچول او هلته تا زما سره يو لوظ وکړو. اوس تۀ هغه مُلک ته واپس لاړ شه چرته چې تۀ پېدا شوے يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(874, 'Genesis 31:14', 'Genesis', 31, 14, '&nbsp;راحيل او لِياه يعقوب ته ووئيل، ”مونږ ته زمونږ د پلار په ميراث کښې هيڅ هم پاتې نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(875, 'Genesis 31:15', 'Genesis', 31, 15, '&nbsp;هغه مونږ په پردو کښې شمېرى. هغۀ مونږه خرڅې کړې يُو او زمونږ په سر هغۀ چې څومره روپۍ اخستې وې هغه ټولې يې ختمې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(876, 'Genesis 31:16', 'Genesis', 31, 16, '&nbsp;هغه ټول دولت کوم چې خُدائ پاک زمونږ د پلار نه اخستے دے هغه زمونږ او زمونږ د بچو دے. چې تا ته خُدائ پاک څۀ فرمائيلى دى هم هغسې وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(877, 'Genesis 31:19', 'Genesis', 31, 19, '&nbsp;لابن د خپلو ګډو نه وړۍ کلولو دپاره تلے وو او چې هغه نۀ وو نو راحيل د خپل پلار د کور بُتان پټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(878, 'Genesis 31:20', 'Genesis', 31, 20, '&nbsp;يعقوب لابن دوکه کړو ځکه چې هغه يې د خپل تګ نه خبر نۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(879, 'Genesis 31:21', 'Genesis', 31, 21, '&nbsp;د هغۀ سره چې څۀ وُو هغه يې راواخستل او په تېزۍ سره لاړو. هغه د فرات د سيند نه پورې وتلو او د غرونو مُلک جِلعاد ته روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(880, 'Genesis 31:22', 'Genesis', 31, 22, '&nbsp;درې ورځې وروستو لابن خبر شو چې يعقوب تښتېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(881, 'Genesis 31:23', 'Genesis', 31, 23, '&nbsp;نو هغۀ خپل سړى ځان سره کړل او اووۀ ورځې په يعقوب پسې وُو چې د غرونو مُلک جِلعاد سره يې رايسار کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(882, 'Genesis 31:24', 'Genesis', 31, 24, '&nbsp;په هغه شپه خُدائ پاک لابن ته په خوب کښې راغلو او هغۀ ته يې ووئيل، ”خيال کوه چې يعقوب ته هيڅ هم ونۀ وائې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(883, 'Genesis 31:25', 'Genesis', 31, 25, '&nbsp;لابن يعقوب د جِلعاد په غرونو کښې ګېر کړو، چرته چې يعقوب خېمه لګولې وه. لابن هم د خپلوانو سره هلته خېمه ولګوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(884, 'Genesis 31:26', 'Genesis', 31, 26, '&nbsp;لابن يعقوب ته ووئيل، ”تا ولې زۀ دوکه کړم او زما لوڼه دې داسې بوتلې لکه د تُورې په زور دې نيولې وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(885, 'Genesis 31:27', 'Genesis', 31, 27, '&nbsp;تا ولې زۀ دوکه کړم او زۀ دې خبر هم نۀ کړم او وتښتېدلې؟ کۀ تا ما ته وئيلى وے، نو ما به تۀ په خپله مخه د تمبل، رباب او د سندرو جشن سره رُخصت کړے وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(886, 'Genesis 31:28', 'Genesis', 31, 28, '&nbsp;تا دې ته هم پرې نۀ ښودم چې ما خپل نمسى او لوڼه ښُکل کړے وے او دوئ ته مې په مخه ښه وئيلى وے. دا دې د کم عقلتوب کار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(887, 'Genesis 31:29', 'Genesis', 31, 29, '&nbsp;زۀ تا ته د نقصان رسولو زور لرم، خو تېره شپه ستا د پلار خُدائ پاک ما له خبردارے راکړو چې تا ته هيڅ هم ونۀ وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(888, 'Genesis 31:30', 'Genesis', 31, 30, '&nbsp;ما ته پته وه چې تۀ ځې ځکه چې تۀ واپس کور له تلو ته ډېر بې‌صبره وې، خو زما د کور هغه بُتان دې ولې پټ کړل؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(889, 'Genesis 31:31', 'Genesis', 31, 31, '&nbsp;يعقوب جواب ورکړو، ”زۀ يرېدم، زما خيال دا وو چې تۀ خپلې لوڼه زما نه په زور بوځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(890, 'Genesis 31:32', 'Genesis', 31, 32, '&nbsp;خو کۀ تا دلته د چا سره هم ستا بُتان پېدا کړل، نو هغه به ژوندے نۀ شى پرېښودلے. دلته زمونږ د خپلوانو په مخکښې يې وګوره، چې ستا څۀ څيز هم وى نو خپل څيز يوسه.“ يعقوب ته پته نۀ وه چې د لابن بُتان راحيل پټ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(891, 'Genesis 31:33', 'Genesis', 31, 33, '&nbsp;لابن لاړو او د يعقوب خېمه يې ولټوله، بيا هغه د لِياه خېمې او د هغه دوه وينځو خېمې ته لاړو، خو هغۀ خپل بُتان ونۀ موندل. بيا هغه د راحيل خېمې ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(892, 'Genesis 31:34', 'Genesis', 31, 34, '&nbsp;راحيل د کور هغه بُتان راخستى وُو او هغه يې د اوښ د زين په کڅوړه کښې کېښودلى وُو او په هغې باندې ناسته وه. لابن هغه ټوله خېمه ولټوله، خو هغه يې ونۀ موندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(893, 'Genesis 31:35', 'Genesis', 31, 35, '&nbsp;راحيل خپل پلار ته ووئيل، ”پلاره، ما ته مۀ غصه کېږه، خو چې تۀ دلته يې ستا په مخکښې زۀ نۀ شم پاڅېدلے، په ما د ښځو بيمارى راغلې ده.“ لابن لټون وکړو خو د خپل کور هغه بُتان يې پېدا نۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(894, 'Genesis 31:36', 'Genesis', 31, 36, '&nbsp;بيا يعقوب غصه شو، ”ما څۀ بد کړى دى؟ زما ګناه څۀ ده چې تۀ داسې تېز په ما پسې راورسېدې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(895, 'Genesis 31:37', 'Genesis', 31, 37, '&nbsp;اوس چې زما سره څۀ دى هغه ټول دې ولټول، تا د خپل کور کوم يو څيز موندلے دے چې هغه ستا وى؟ دا دلته بهر ښکاره کېږده چې زما او ستا خپلوان يې وګورى او دوئ به فېصله وکړى چې په مونږ کښې څوک په حقه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(896, 'Genesis 31:38', 'Genesis', 31, 38, '&nbsp;زۀ تا سره د شلو کالو نه يم، ستا ګډو او ستا چېلو په يو کال هم بچے نۀ دے ضائع کړے او ما يو ګډ هم ستا د رَمو نه نۀ دے خوړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(897, 'Genesis 31:39', 'Genesis', 31, 39, '&nbsp;چې کله هم يو ځنګلى ځناور ستا ګډه خوړلې ده، ما هغه تاوان په خپله درکړے دے. تا هر هغه څيز زما نه غوښتے دے چې چا د ورځې يا شپې پټ کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(898, 'Genesis 31:40', 'Genesis', 31, 40, '&nbsp;ډېر ځل زۀ د ورځې ګرمۍ وهلے يم او د شپې يخنۍ اوچ کړے يم. او زما خوب تښتېدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(899, 'Genesis 31:41', 'Genesis', 31, 41, '&nbsp;د شلو کالو نه زۀ ستا په کور کښې يم. څوارلس کاله ما ستا د دوو لوڼو او شپږ کاله ستا د رَمو دپاره، ستا خِدمت کړے دے. او بيا هم، تا لس ځل زما مزدورى بدله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(900, 'Genesis 31:42', 'Genesis', 31, 42, '&nbsp;کۀ زما د پلار خُدائ پاک، کوم چې د اِبراهيم او اِسحاق خُدائ پاک دے، زما مل نۀ وے، نو تا به زۀ مخکښې خالى لاسونه لېږلے وے. خو خُدائ پاک زما تکليف او کوم خِدمت چې ما کړے دے هغه ليدلے دے او ځکه خُدائ پاک تېره شپه تۀ ملامته کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');